def enclosed_regions(g):
    H,W=len(g),len(g[0])
    seen=[[False]*W for _ in range(H)]
    # flood zeros with 8-connectivity from border
    st=[(i,j) for i in range(H) for j in range(W) if (i in(0,H-1) or j in(0,W-1)) and g[i][j]==0]
    outside=set(st)
    while st:
        a,b=st.pop()
        for da in(-1,0,1):
            for db in(-1,0,1):
                x,y=a+da,b+db
                if 0<=x<H and 0<=y<W and g[x][y]==0 and (x,y) not in outside:
                    outside.add((x,y));st.append((x,y))
    regs=[]
    seen2=set()
    for i in range(H):
        for j in range(W):
            if g[i][j]==0 and (i,j) not in outside and (i,j) not in seen2:
                cells=[(i,j)];seen2.add((i,j));st=[(i,j)]
                while st:
                    a,b=st.pop()
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and g[x][y]==0 and (x,y) not in outside and (x,y) not in seen2:
                            seen2.add((x,y));st.append((x,y));cells.append((x,y))
                regs.append(cells)
    return regs
