def transform(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; regs=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==0 and not seen[i][j]:
                st=[(i,j)];seen[i][j]=True;cells=[]
                while st:
                    a,b=st.pop();cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and g[x][y]==0 and not seen[x][y]:
                            seen[x][y]=True;st.append((x,y))
                regs.append(cells)
    sizes=[len(r) for r in regs]
    mx,mn=max(sizes),min(sizes)
    g=[row[:] for row in g]
    for r in regs:
        v = 8 if len(r)==mx else (7 if len(r)==mn else 0)
        if v:
            for a,b in r: g[a][b]=v
    return g
